import Foundation

struct PayloadInspector {
    func shouldIntercept(payload: [String: Any]) -> Bool {
        let aps = payload["aps"] as? [String: Any]
        let mutableContent = aps?["mutable-content"] as? Int
        return mutableContent == 1
    }
}

let samplePayload: [String: Any] = ["aps": ["alert": "Hi", "mutable-content": 1]]
let inspector = PayloadInspector()
print("Intercept: \(inspector.shouldIntercept(payload: samplePayload))")

import Foundation

struct SilentPushValidator {
    func isSilent(aps: [String: Any]) -> Bool {
        let hasContentAvailable = (aps["content-available"] as? Int) == 1
        let hasNoAlert = aps["alert"] == nil
        return hasContentAvailable && hasNoAlert
    }
}

let apsDict: [String: Any] = ["content-available": 1]
let validator = SilentPushValidator()
print("Silent: \(validator.isSilent(aps: apsDict))")

import Foundation

class TokenSyncManager {
    var storedToken: String = "tokenA"

    func updateTokenIfChanged(newToken: String) -> Bool {
        if newToken != storedToken {
            storedToken = newToken
            return true
        }
        return false
    }
}

let manager = TokenSyncManager()
let didChange = manager.updateTokenIfChanged(newToken: "tokenB")
print("Changed: \(didChange)")

