import Foundation

struct HexTokenConverter {
    func convert(bytes: [UInt8]) -> String {
        bytes.map { String(format: "%02x", $0) }.joined()
    }
}

func testConverter() {
    let converter = HexTokenConverter()
    print("Hex: \(converter.convert(bytes: [0xaa, 0xbb, 0xcc]))")
}

testConverter()

